        loc_patterns['city, UK-suffix'] += 1
    elif re.search(r',\s*United States', loc, re.I) or re.search(r',\s*(PA|NH|AL|OH|TX|NY)\s*,', loc, re.I):
        loc_patterns['US location'] += 1
