        loc_patterns['AU location'] += 1
    elif re.search(r'Remote|Work from home|Home.based', loc, re.I):
        loc_patterns['Remote'] += 1
    elif re.search(r'Hybrid', loc, re.I):
        loc_patterns['Hybrid'] += 1
    elif loc.strip() == '':
        loc_patterns['empty'] += 1
    elif ',' not in loc and len(loc.split()) <= 2:
        loc_patterns['bare city/town'] += 1
    else:
        loc_patterns['other'] += 1

print("=== Location format distribution (1529 raw jobs) ===")
